            hits.append(os.path.join(root, f))
print("JSON files outside quarantine:", hits)
# Check factors dir structure
for root, dirs, files in os.walk('factors'):
    print(root, "->", dirs, files)
# Any artifact/npy/csv signal files outside quarantine?
for root, dirs, files in os.walk('.'):
    if 'quarantine' in root or '__pycache__' in root: continue
    for f in files:
        if f.endswith(('.npy','.npz','.pkl','.parquet')):
            print("ARTIFACT:", os.path.join(root, f))
EOF

