        d = d[0] if d else {}
    art = d.get("signal_artifact")
    if isinstance(art, str):
        art = _dec(art); d["signal_artifact"] = art
    return d

# ---- check mom_10d_skip5 raw ----
print("=== mom_10d_skip5 raw ===")
