import numpy as np, pandas as pd, json
from alphacrafter.sim.utils import get_stock_daily_data, get_index_daily_data

TRADABLE = ["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
frames = {}
for a in TRADABLE:
    df = get_stock_daily_data(symbol=a, days=260)
    if df is not None and len(df) >= 30:
        df = df.copy()
        for c in ['open','high','low','close']:
            df[c] = df[c].astype(float)
        frames[a] = df
print('assets with data:', len(frames))
print('last date:', sorted(frames.values(), key=lambda x: x['date'].iloc[-1])[-1]['date'].iloc[-1])

# ---- Regime stats through last completed bar (2026-10-29) ----
rows = []
for a, df in frames.items():
    c = df['close']
    r = np.log(c/c.shift(1)).dropna()
    r10 = np.log(c.iloc[-1]/c.iloc[-11])
    r20 = np.log(c.iloc[-1]/c.iloc[-21])
    rows.append((a, r.tail(20).mean(), r10, r20, r.tail(60).std()*np.sqrt(252)))
reg = pd.DataFrame(rows, columns=['asset','m20d_daily','r10','r20','ann_vol'])
print('\n=== cross-asset regime (through 2026-10-29) ===')
print(reg.sort_values('r10').to_string(index=False, float_format=lambda x: f'{x:+.4f}'))
print('\nmean 20d daily ret (strategy regime metric):', reg['m20d_daily'].mean())
print('median 10d ret:', reg['r10'].median(), '| dispersion (std of 10d):', reg['r10'].std())

# ---- VIX level ----
try:
    vix = get_index_daily_data(symbol='VIX', days=120)
    if vix is not None and len(vix):
        v = vix['close'].astype(float)
        print('\nVIX last:', round(float(v.iloc[-1]),2), '| 20d ago:', round(float(v.iloc[-20]),2), '| 60d ago:', round(float(v.iloc[-60]),2))
except Exception as e:
    print('vix err', e)

# ---- Factor signal correlation (recent 60d, cross-sectional rank vectors) ----
def fvals(df, fid):
    o,h,l,c = df['open'],df['high'],df['low'],df['close']
    if fid=='miner2_20260715_nclv_1d': x = -(c-l)/(h-l)
    elif fid=='miner2_20260715_nclv_2d': x = -(c-l.rolling(2).min())/(h.rolling(2).max()-l.rolling(2).min())
    elif fid=='miner2_20260715_nclv_3d': x = -(c-l.rolling(3).min())/(h.rolling(3).max()-l.rolling(3).min())
    elif fid=='miner2_20260715_rev_1d': x = -np.log(c/c.shift(1))
    elif fid=='miner2_20260715_rev_2d': x = -np.log(c/c.shift(2))
    elif fid=='miner2_20260715_nbody_1d': x = -(c-o)/(h-l)
    elif fid=='mom_120d_skip5': x = np.log(c.shift(5)/c.shift(125))
    elif fid=='vol_of_vol20x60': x = np.log(c/c.shift(1)).rolling(20).std().rolling(60).std()
    elif fid=='vix_beta_cond_60x20': x = None  # needs VIX; handle below
    else: x = None
    return x.replace([np.inf,-np.inf], np.nan) if x is not None else None

SEL = ["miner2_20260715_nclv_1d","miner2_20260715_nclv_2d","miner2_20260715_nclv_3d",
       "miner2_20260715_rev_1d","miner2_20260715_rev_2d","miner2_20260715_nbody_1d",
       "mom_120d_skip5","vol_of_vol20x60","vix_beta_cond_60x20"]

# build aligned date index (union of last 60 common dates)
dates = None
for a,df in frames.items():
    dts = set(df['date'].astype(str))
    dates = dts if dates is None else (dates & dts)
dates = sorted(dates)[-60:]
print('\ncommon dates for corr:', len(dates))

signals = {}
for fid in SEL:
    mat = {}
    for a,df in frames.items():
        s = df.set_index(df['date'].astype(str))
        if fid=='vix_beta_cond_60x20':
            if vix is not None and len(vix):
                vx = vix.set_index(vix['date'].astype(str))['close'].astype(float)
                r_asset = np.log(s['close']/s['close'].shift(1))
                dvix = vx.diff()
                j = pd.concat([r_asset, dvix], axis=1, join='inner').dropna()
                if len(j) >= 70:
                    b = j.iloc[:,0].rolling(60).cov(j.iloc[:,1])/j.iloc[:,1].rolling(60).var()
                    mat[a] = b
                else:
                    mat[a] = pd.Series(dtype=float)
            else:
                mat[a] = pd.Series(dtype=float)
        else:
            x = fvals(df, fid)
            mat[a] = pd.Series(x.values, index=df['date'].astype(str))
    panel = pd.DataFrame(mat)
    panel = panel.reindex(dates)
    signals[fid] = panel

# cross-sectional rank each day, then temporal corr of rank vectors
rankmats = {}
for fid, panel in signals.items():
    rm = panel.rank(axis=1, pct=True)
    rankmats[fid] = rm

names = SEL
n = len(names)
corr = np.zeros((n,n))
for i in range(n):
    for j in range(n):
        a = rankmats[names[i]].values
        b = rankmats[names[j]].values
        mask = np.isfinite(a) & np.isfinite(b)
        if mask.sum() > 20:
            aa = a[mask]; bb = b[mask]
            corr[i,j] = np.corrcoef(aa, bb)[0,1]
        else:
            corr[i,j] = np.nan
print('\n=== pairwise signal corr (recent 60d) ===')
hdr = '            ' + ''.join(f'{x[-10:]:>11}' for x in names)
print(hdr)
for i in range(n):
    print(f'{names[i][-22:]:>12}' + ''.join(f'{corr[i,j]:>11.2f}' for j in range(n)))
mx = np.nanmax(np.abs(corr - np.eye(n)))
print('\nmax |off-diag corr| among selected:', round(float(mx),3))

# latest cross-sectional values (last bar) for signal sanity
print('\n=== latest factor value per asset (z of rank) ===')
last = {}
for fid in SEL:
    panel = signals[fid]
    last[fid] = panel.iloc[-1].rank(pct=True)
out = pd.DataFrame(last)
print(out.round(2).to_string())
