import pandas as pd, numpy as np, glob, os

files = sorted(glob.glob('../persistent/stock_data/*.csv'))
data={}
for f in files:
    name=os.path.basename(f).replace('.csv','')
    df=pd.read_csv(f)
    df.columns=[c.strip() for c in df.columns]
    dc='date' if 'date' in df.columns else df.columns[0]
    df[dc]=pd.to_datetime(df[dc]); df=df.sort_values(dc).reset_index(drop=True)
    data[name]=df

# Build OHLCV panel per asset
assets=list(data.keys())
px={k: data[k].set_index('date') for k in assets}

def factor_series(asset, fid):
    df=data[asset].set_index('date').sort_index()
    o=df['open'].astype(float); h=df['high'].astype(float); l=df['low'].astype(float); c=df['close'].astype(float)
    if fid=='id_rev_1d': return -(c/o - 1)
    if fid=='nbody_1d': return -(c-o)/(h-l)
    if fid=='nclv_1d': return -(c-l)/(h-l)
    if fid=='nclv_2d': return -(c-l.rolling(2).min())/(h.rolling(2).max()-l.rolling(2).min())
    if fid=='nclv_3d': return -(c-l.rolling(3).min())/(h.rolling(3).max()-l.rolling(3).min())
    if fid=='nclv_5d': return -(c-l.rolling(5).min())/(h.rolling(5).max()-l.rolling(5).min())
    if fid=='rev_1d': return -np.log(c/c.shift(1))
    if fid=='rev_1d_vs': return -np.log(c/c.shift(1))/c.pct_change().rolling(20).std()
    if fid=='rev_2d': return -np.log(c/c.shift(2))
    if fid=='rev_3d': return -np.log(c/c.shift(3))
    if fid=='rev_5d': return -np.log(c/c.shift(5))
    if fid=='mom_120d_skip5': return c.shift(5)/c.shift(125)-1
    if fid=='vol_of_vol20x60': return c.pct_change().rolling(20).std().rolling(60).std()
    return None

vix=pd.read_csv('../persistent/index_data/VIX.csv'); vix.columns=[x.strip() for x in vix.columns]
vix['date']=pd.to_datetime(vix['date']); vix=vix.sort_values('date').set_index('date')['close'].astype(float)

# forward returns: 10d
fwd={}
for a in assets:
    c=data[a].set_index('date')['close'].astype(float)
    fwd[a]=c.shift(-10)/c - 1

# Build factor panels (aligned to common dates via intersection on date index of close)
fids=['id_rev_1d','nbody_1d','nclv_1d','nclv_2d','nclv_3d','nclv_5d','rev_1d','rev_1d_vs','rev_2d','rev_3d','rev_5d','mom_120d_skip5','vol_of_vol20x60','vix_beta_cond_60x20']

F={}
for fid in fids:
    cols={}
    for a in assets:
        s=factor_series(a,fid)
        if s is not None:
            cols[a]=s
    F[fid]=pd.DataFrame(cols)

# VIX-beta conditional factor
vixb={}
for a in assets:
    c=data[a].set_index('date')['close'].astype(float)
    ar=c.pct_change(); vr=vix.pct_change()
    b=ar.rolling(60).cov(vr)/vr.rolling(60).var()
    vm=vix/vix.shift(20)-1
    vixb[a]=(-b*vm).reindex(c.index)
F['vix_beta_cond_60x20']=pd.DataFrame(vixb)

# fwd returns panel
Fwd=pd.DataFrame(fwd)

# Common date range up to 2026-11-12
cut='2026-11-12'
def ic_series(fid, horizon_days=10, start=None, end=cut):
    fs=F[fid]
    fr=Fwd
    idx=fs.index.intersection(fr.index)
    fs=fs.loc[idx]; fr=fr.loc[idx]
    ics=[]
    dates=[]
    for t in range(horizon_days, len(idx)):
        d=idx[t]
        if d>pd.Timestamp(end): break
        x=fs.iloc[t-horizon_days]; y=fr.iloc[t-horizon_days]
        m=(x.notna()&y.notna())
        if m.sum()>=8:
            ics.append(np.corrcoef(x[m].rank(), y[m].rank())[0,1])
            dates.append(d)
    return pd.Series(ics, index=dates)

print("=== Recent 10d-horizon IC (rank) by window, data through 2026-11-12 ===")
print(f"{'factor':22s} {'120d IC':>8s} {'120d ICIR':>9s} {'60d IC':>8s} {'60d ICIR':>9s} {'30d IC':>8s}")
res={}
for fid in fids:
    ic=ic_series(fid)
    ic120=ic.tail(120); ic60=ic.tail(60); ic30=ic.tail(30)
    def m(s):
        return (s.mean(), s.mean()/s.std()*np.sqrt(len(s)) if s.std()>0 else np.nan)
    a=m(ic120); b=m(ic60); c=m(ic30)
    res[fid]=(ic120,ic60,ic30)
    print(f"{fid:22s} {a[0]:8.4f} {a[1]:9.2f} {b[0]:8.4f} {b[1]:9.2f} {c[0]:8.4f}")
