import json, glob, os

def get_validation(d):
    v = d.get('validation', {})
    # print compact summary
    out = {}
    for k in ('ic_mean','ic','IC','icir','ICIR','sharpe','hit_rate','turnover','coverage','ic_series','rank_ic','rank_icir','q','quality'):
        if k in v: out[k]=v[k]
